   // #endregion Public Methods\n\n    private buildValueString(id: string, value: any): string {\n        if (id == null) {\n            return `${value}`;\n        }\n\n        // fix: Ensuring compatibility with the old FormsModule implementation\n        // todo: Will be removed in newer versions of Angular\n        if (typeof value === 'number') {\n            return `${value}`;\n        }\n\n        if (typeof value === 'string') {\n            value = `'${value}'`;\n        }\n\n        if (value && typeof value === 'object') {\n            value = 'Object';\n        }\n\n        return `${id}: ${value}`.slice(0, 50);\n    }\n\n    private setElementValue(value: string): void {\n        this._renderer.setProperty(this._element.nativeElement, 'value', value);\n    }\n}\n\n/**\n * Component for SacListboxCommon. Extends SacBaseSelectControl\n */\n@Directive()\nexport class SacListboxCommon extends SacBaseSelectControl> {\n    // #region Properties\n\n    /**\n     * Number of rows\n     */\n    @Input() public rowsize = 5;\n    /**\n     * Resource key for validation message required at control\n     */\n    @Input() public validationmessagerequired: string = this.validationKeyService.ValidationErrorRequired;\n\n    /**\n     * Resource key for validation message required in validation summary\n     */\n    @Input()\n    public validationmessagesummaryrequired: string = this.validationKeyService.ValidationErrorSummaryRequired;\n\n    /**\n     * ViewChildren method\n     */\n    @ViewChildren(SacListboxOptionCommon)\n    public contentOptions: QueryList;\n\n    /**\n     * Option list\n     */\n    public optionlist: Array = new Array();\n\n    // #endregion Properties\n\n    // #region Public Methods\n\n    /**\n     * Getter for selected items\n     */\n    public getSelectedItems(selectelement: any) {\n        const selectedValues: Array = new Array();\n\n        if (selectelement.hasOwnProperty('selectedOptions')) {\n            const options: HTMLCollection = selectelement.selectedOptions;\n            for (let i = 0; i selectelement.options;\n            for (let i = 0; i ) {\n        if (this.optionlist && value) {\n            this.optionlist.forEach((itm) => {\n                if (value.indexOf(itm.value) >= 0) {\n                    itm._setSelected(true);\n                }\n            });\n        }\n\n        super.writeValue(value);\n    }\n\n    // #endregion Public Methods\n}\n\n/**\n * Wrapper for HTML select\n */\nabstract class HTMLCollection {\n    // #region Properties\n\n    /**\n     * Length\n     */\n    public length: number;\n\n    // #endregion Properties\n\n    // #region Public Abstract Methods\n\n    /**\n     * Option-Item\n     */\n    public abstract item(_: number): HTMLOption;\n\n    // #endregion Public Abstract Methods\n}\n\n// #endregion Classes\n\n    \n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"interfaces/IAbstractControlLabelExtension.html":{"url":"interfaces/IAbstractControlLabelExtension.html","title":"interface - IAbstractControlLabelExtension","body":"\n                   \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n  Interfaces\n  \n  IAbstractControlLabelExtension\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n\n\n\n    \n        \n            File\n        \n        \n            projects/sac-common/src/interfaces/iabstractcontrollabel.ts\n        \n\n\n            \n                Description\n            \n            \n                Interface to extend FormControl with a label property used for form field labeling.\n\n            \n\n\n        \n            Index\n            \n                \n                    \n                        \n                            Properties\n                        \n                    \n                    \n                        \n                            \n                               